"""Shared abstract models.

Concrete financial models are added in later phases. These bases centralize the
UUID primary key and audit timestamps without creating database tables.
"""

import uuid

from django.db import models


class UUIDModel(models.Model):
    """Abstract model with a UUID primary key generated by ``uuid.uuid4``."""

    id = models.UUIDField(primary_key=True, default=uuid.uuid4, editable=False)

    class Meta:
        abstract = True


class TimeStampedModel(models.Model):
    """Abstract model with immutable creation and automatic update timestamps."""

    created_at = models.DateTimeField(auto_now_add=True)
    updated_at = models.DateTimeField(auto_now=True)

    class Meta:
        abstract = True


class BaseModel(UUIDModel, TimeStampedModel):
    """Convenience base combining UUID identity and audit timestamps."""

    class Meta:
        abstract = True
